package org.apache.commons.cli;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

class CommandLine_GetParsedOptionValuesTest {

    /**
     * A testable subclass of CommandLine that overrides the getParsedOptionValues(Option, T[])
     * to capture the arguments passed and return a preconfigured array.
     */
    private static class TestableCommandLine extends CommandLine {
        Option lastOption;
        Object lastDefault;
        Object returnValue;

        @Override
        @SuppressWarnings("unchecked")
        public <T> T[] getParsedOptionValues(final Option option, final T[] defaultValue) throws ParseException {
            this.lastOption = option;
            this.lastDefault = defaultValue;
            return (T[]) returnValue;
        }
    }

    @Test
    void testDelegatesWhenOptionNotFound() throws Exception {
        TestableCommandLine cl = new TestableCommandLine();
        // configure return value to be a String[] for this test
        cl.returnValue = new String[] { "returned" };

        String[] defaultVal = new String[] { "def1", "def2" };
        String[] result = cl.getParsedOptionValues("nonexistent", defaultVal);

        // resolveOption should return null (no options present), so delegate gets option == null
        assertArrayEquals(new String[] { "returned" }, result);
        assertNull(cl.lastOption, "Expected resolveOption to return null when options list is empty");
        assertSame(defaultVal, cl.lastDefault, "Expected the same default array instance to be passed through");
    }

    @Test
    void testDelegatesWhenOptionFoundByOpt() throws Exception {
        TestableCommandLine cl = new TestableCommandLine();
        // configure return value to be an Integer[] for this test
        cl.returnValue = new Integer[] { 99 };

        // create an Option and insert into the private options list of CommandLine instance
        Option opt = new Option("a", "alpha", true, "desc");

        Field optionsField = CommandLine.class.getDeclaredField("options");
        optionsField.setAccessible(true);
        @SuppressWarnings("unchecked")
        List<Option> optionsList = (List<Option>) optionsField.get(cl);
        optionsList.add(opt);

        Integer[] defaultVal = new Integer[] { 1, 2 };
        Integer[] result = cl.getParsedOptionValues("a", defaultVal);

        assertArrayEquals(new Integer[] { 99 }, result);
        assertSame(opt, cl.lastOption, "Expected the option found by short opt to be passed");
        assertSame(defaultVal, cl.lastDefault, "Expected the same default array instance to be passed through");
    }

    @Test
    void testDelegatesWhenOptionFoundByLongOptWithHyphens() throws Exception {
        TestableCommandLine cl = new TestableCommandLine();
        // configure return value to be a String[] for this test
        cl.returnValue = new String[] { "ok" };

        // create an Option with longOpt "beta" and insert into private options list
        Option opt = new Option("b", "beta", true, "desc");

        Field optionsField = CommandLine.class.getDeclaredField("options");
        optionsField.setAccessible(true);
        @SuppressWarnings("unchecked")
        List<Option> optionsList = (List<Option>) optionsField.get(cl);
        optionsList.add(opt);

        String[] defaultVal = new String[] { "x" };
        // use leading hyphens to ensure stripLeadingHyphens/resolution works
        String[] result = cl.getParsedOptionValues("--beta", defaultVal);

        assertArrayEquals(new String[] { "ok" }, result);
        assertSame(opt, cl.lastOption, "Expected the option found by long opt to be passed");
        assertSame(defaultVal, cl.lastDefault, "Expected the same default array instance to be passed through");
    }
}

